func (u *TrackingProfileUpsertBulk) Update(set func(*TrackingProfileUpsert)) *TrackingProfileUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&TrackingProfileUpsert{UpdateSet: update})
	}))
	return u
}

